match.source:
match [1, 2, 3] {
  [a, b, c] => @"rrs-r6-match"!(a + b + c)
  _ => Nil
}

r9_play_replay_equality.program:
new loop, result, stdout(`rho:io:stdout`) in {
  contract loop(@n, @acc) = {
    match n {
      0 => result!(acc)
      _ => loop!(n - 1, acc + n)
    }
  } |
  loop!(4, 0) |
  for (@total <- result) {
    @"rrs-r9-total"!(total) |
    stdout!(["rrs-r9", total])
  } |
  @"rrs-r9-left"!(1) |
  @"rrs-r9-right"!(2) |
  for (@l <- @"rrs-r9-left" & @r <- @"rrs-r9-right") { @"rrs-r9-joined"!(l + r) } |
  @"rrs-r9-peek"!("seen") |
  for (@s <<- @"rrs-r9-peek") { @"rrs-r9-peeked"!(s) } |
  @"rrs-r9-persistent"!!(10) |
  for (@p <- @"rrs-r9-persistent") { @"rrs-r9-persistent-seen"!(p) }
}
